          id: "full-name",
          label: "Full name",
          name: "fullName",
          type: "text",
          autocomplete: "name",
          required: true,
          error: "Error: Enter your full name.",
        },
        {
          id: "email-address",
          label: "Email address",
          name: "email",
          type: "email",
          autocomplete: "email",
          required: true,
          error: "Error: Enter a valid email address.",
        },
        {
          id: "phone-number",
          label: "Phone number",
          name: "phone",
          type: "tel",
          autocomplete: "tel",
          required: false,
          helpText: "Use a number like +1 555 123 4567.",
        },
      ];

      function fieldDescriptionIds({ helpId, errorId }) {
        return [helpId, errorId].filter(Boolean).join(" ");
      }

      function formField({
        id,
        label,
        name,
        type,
        autocomplete,
        required,
        helpText,
        error,
