        const helpId = helpText ? `${id}-help` : "";
        const errorId = `${id}-error`;
        const describedBy = fieldDescriptionIds({ helpId, errorId: "" });

        return `
          <div class="form-field">
            <label for="${id}">
              ${label}
              ${required ? '<span class="required-indicator" aria-hidden="true">*</span>' : ""}
            </label>
            <input
              id="${id}"
              name="${name}"
              type="${type}"
              autocomplete="${autocomplete}"
              ${required ? "required" : ""}
