        input.addEventListener("input", () => {
          if (!state.attemptedSubmit) {
            return;
          }

          validateField(input);
        });

        input.addEventListener("blur", () => {
          if (!state.attemptedSubmit) {
            return;
          }

          validateField(input);
        });
      });
    </script>
