   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main id="main-content"></main>

     <script>
       const state = {
         attemptedSubmit: false,
       };

       const fieldConfig = [
         {
           id: "full-name",
           label: "Full name",
           name: "fullName",
           type: "text",
           autocomplete: "name",
           required: true,
           error: "Error: Enter your full name.",
         },
         {
           id: "email-address",
           label: "Email address",
           name: "email",
           type: "email",
           autocomplete: "email",
           required: true,
           error: "Error: Enter a valid email address.",
         },
         {
           id: "phone-number",
           label: "Phone number",
           name: "phone",
           type: "tel",
           autocomplete: "tel",
           required: false,
           helpText: "Use a number like +1 555 123 4567.",
         },
       ];

       function fieldDescriptionIds({ helpId, errorId }) {
         return [helpId, errorId].filter(Boolean).join(" ");
       }

       function formField({
         id,
         label,
         name,
         type,
         autocomplete,
         required,
         helpText,
         error,
       }) {
         const helpId = helpText ? `${id}-help` : "";
         const errorId = `${id}-error`;
         const describedBy = fieldDescriptionIds({ helpId, errorId: "" });

         return `
           <div class="form-field">
             <label for="${id}">
               ${label}
               ${required ? '<span class="required-indicator" aria-hidden="true">*</span>' : ""}
             </label>
             <input
               id="${id}"
               name="${name}"
               type="${type}"
               autocomplete="${autocomplete}"
               ${required ? "required" : ""}
               ${type === "tel" ? 'inputmode="tel"' : ""}
               ${describedBy ? `aria-describedby="${describedBy}"` : ""}
             />
             ${helpText ? `<p class="field-hint" id="${helpId}">${helpText}</p>` : ""}
             <p class="field-error" id="${errorId}" hidden aria-live="polite"></p>
           </div>
         `;
       }

       function app() {
         return `
           <section class="page-shell" aria-labelledby="page-title">
             <div class="hero">
               <span class="eyebrow">Support</span>
               <h1 id="page-title">Contact our support team</h1>
               <p class="lede">
                 Send us your details and we&rsquo;ll route your request to the right person.
                 Keep the information accurate so we can reply without delays.
               </p>
             </div>

             <div class="panel">
               <p class="form-note"><span aria-hidden="true">*</span> Required fields</p>
               <div class="form-status" id="form-status" aria-live="polite" aria-atomic="true"></div>
               <form id="support-form" novalidate>
                 ${fieldConfig.map(formField).join("")}
                 <div class="actions">
                   <button type="submit">Send message</button>
                 </div>
               </form>
             </div>
           </section>
         `;
       }

       function validateField(input) {
         const errorEl = document.getElementById(`${input.id}-error`);
         const describedByIds = [];
         const helpEl = document.getElementById(`${input.id}-help`);

         if (helpEl) {
           describedByIds.push(helpEl.id);
         }

         let errorText = "";

         if (input.id === "full-name" && input.value.trim() === "") {
           errorText = "Error: Enter your full name.";
         } else if (input.required && input.validity.valueMissing) {
           errorText = input.id === "full-name"
             ? "Error: Enter your full name."
             : "Error: Enter your email address.";
         } else if (input.type === "email" && input.value && !input.validity.valid) {
           errorText = "Error: Enter a valid email address.";
         }

         if (errorText) {
           input.setAttribute("aria-invalid", "true");
           errorEl.textContent = errorText;
           errorEl.hidden = false;
           describedByIds.push(errorEl.id);
         } else {
           input.removeAttribute("aria-invalid");
           errorEl.textContent = "";
           errorEl.hidden = true;
         }

         if (describedByIds.length) {
           input.setAttribute("aria-describedby", describedByIds.join(" "));
         } else {
           input.removeAttribute("aria-describedby");
         }

         return !errorText;
       }

       function validateForm(form) {
         const inputs = Array.from(form.querySelectorAll("input"));
         const firstInvalid = inputs.find((input) => !validateField(input));

         return {
           isValid: !firstInvalid,
           firstInvalid,
         };
       }

       const main = document.getElementById("main-content");
       main.innerHTML = app();

       const form = document.getElementById("support-form");
       const status = document.getElementById("form-status");
       const inputs = Array.from(form.querySelectorAll("input"));

       form.addEventListener("submit", (event) => {
         state.attemptedSubmit = true;
         const { isValid, firstInvalid } = validateForm(form);

         if (!isValid) {
           event.preventDefault();
           status.textContent = "Please fix the highlighted fields.";
           firstInvalid.focus();
           return;
         }

         event.preventDefault();
         status.textContent = "";
       });

       inputs.forEach((input) => {
         input.addEventListener("input", () => {
           if (!state.attemptedSubmit) {
             return;
           }

           validateField(input);
         });

         input.addEventListener("blur", () => {
           if (!state.attemptedSubmit) {
             return;
           }

           validateField(input);
         });
       });
     </script>
   </body>
